6169	  app.get("/api/checkout/resolve/:token", async (req, res) => {
6170	    try {
6171	      const { token } = req.params;
6172	      if (!tokenRateLimit(token)) return res.status(429).json({ message: "Too many requests" });
6173	      const invoice = await getCheckoutInvoiceByToken(token);
6174	      if (!invoice) return res.status(404).json({ message: "Payment link not found" });
6175	      if (invoice.status === "voided") return res.status(410).json({ message: "This payment link has been voided" });
6176	      if (invoice.status === "paid" || invoice.status === "paid_external") return res.status(200).json({ alreadyPaid: true, amountCents: invoice.amountCents });
6177	      const [merchant, party] = await Promise.all([storage.getMerchant(invoice.merchantId), getCheckoutParty(invoice)]);
6178	      if (!merchant || !party) return res.status(404).json({ message: "Payment details unavailable" });
6179	      res.json({
6180	        vertical: invoice.checkoutVertical ?? "property",
6181	        invoiceId: invoice.id, amountCents: invoice.amountCents, dueAt: invoice.dueAt, status: invoice.status,
6182	        merchantId: invoice.merchantId,
6183	        merchantName: merchant.businessName || merchant.name,
6184	        customLogoUrl: merchant.customLogoUrl ?? null,
6185	        propertyAddress: party.address,
6186	        tenantName: party.name,
6187	        coTenantsText: party.coTenantsText ?? null,
6188	        // What the payment is for — lets the branded checkout label the amount
6189	        // ("Rent" vs the one-off charge's description).
6190	        kind: invoice.kind ?? "rent",
6191	        chargeType: invoice.chargeType ?? null,
6192	        description: invoice.checkoutVertical === "trades" ? (invoice.jobDetails ?? "Job invoice") : (invoice.description ?? null),
6193	        // Attached invoice document for one-off charges — surfaced as a
6194	        // "View invoice" link on the branded checkout page.
6195	        documentUrl: invoice.documentUrl ?? null,
6196	        documentName: invoice.documentName ?? null,
6197	        splitEnabled: !!invoice.splitEnabled,
6198	        splitCount: invoice.splitCount ?? null,
6199	        splitPaidCount: invoice.splitPaidCount ?? 0,
6200	      });
6201	    } catch (err) { console.error("[CHECKOUT_RESOLVE]", err); res.status(500).json({ message: "Failed to load payment details" }); }
6202	  });
6203	
6204	  // Tenant chooses how many flatmates to split the rent between (sets splitCount).
6205	  app.post("/api/checkout/:token/split", async (req, res) => {
6206	    try {
6207	      const { token } = req.params;
6208	      if (!tokenRateLimit(token)) return res.status(429).json({ message: "Too many requests" });
6209	      const count = parseInt(String(req.body?.count), 10);
6210	      if (!Number.isInteger(count) || count < 2 || count > 12) return res.status(400).json({ message: "Choose between 2 and 12 people" });
6211	      const invoice = await getCheckoutInvoiceByToken(token);
6212	      if (!invoice) return res.status(404).json({ message: "Payment link not found" });
6213	      if (!invoice.splitEnabled) return res.status(400).json({ message: "Splitting is not enabled for this payment" });
6214	      if (["voided", "paid", "paid_external"].includes(invoice.status)) return res.status(409).json({ message: "Invoice is not payable" });
6215	      if ((invoice.splitPaidCount ?? 0) > 0) return res.status(409).json({ message: "A split is already in progress" });
6216	      await updateCheckoutInvoice(invoice, { splitCount: count });
6217	      res.json({ splitCount: count, splitPaidCount: 0, shareCents: Math.floor(invoice.amountCents / count) });
6218	    } catch (err) { console.error("[CHECKOUT_SPLIT]", err); res.status(500).json({ message: "Failed to set up split" }); }
6219	  });
6220	
6221	  app.post("/api/checkout/pay", async (req, res) => {
6222	    try {
6223	      const { token, payerEmail } = req.body as { token?: string; payerEmail?: string };
6224	      if (!token) return res.status(400).json({ message: "token required" });
6225	      if (!tokenRateLimit(token)) return res.status(429).json({ message: "Too many requests" });
6226	      const invoice = await getCheckoutInvoiceByToken(token);
6227	      if (!invoice) return res.status(404).json({ message: "Payment link not found" });
6228	      if (["voided", "paid", "paid_external"].includes(invoice.status)) return res.status(409).json({ message: "Invoice is not payable" });
6229	      const [merchant, party] = await Promise.all([storage.getMerchant(invoice.merchantId), getCheckoutParty(invoice)]);
6230	      if (!merchant || !party) return res.status(500).json({ message: "Invoice data unavailable" });
6231	      const baseUrl = getBaseUrl(req);
6232	
6233	      // Determine what to charge: the full amount, or one share of a split.
6234	      let chargeCents = invoice.amountCents;
6235	      const isSplit = invoice.splitEnabled && invoice.splitCount && invoice.splitCount > 1;
6236	      if (isSplit) {
6237	        const paid = invoice.splitPaidCount ?? 0;
6238	        if (paid >= invoice.splitCount) return res.status(409).json({ message: "This split is already fully paid" });
6239	        const base = Math.floor(invoice.amountCents / invoice.splitCount);
6240	        const isLastShare = paid === invoice.splitCount - 1;
6241	        chargeCents = isLastShare ? invoice.amountCents - base * (invoice.splitCount - 1) : base;
6242	        // Record the payer's email (for their GST copy) before sending them to the gateway.
6243	        if (typeof payerEmail === "string" && /.+@.+\..+/.test(payerEmail)) {
6244	          const emails: string[] = invoice.splitPayerEmails || [];
6245	          const lower = payerEmail.toLowerCase();
6246	          if (!emails.includes(lower)) await updateCheckoutInvoice(invoice, { splitPayerEmails: [...emails, lower] });
6247	        }
6248	      }
6249	
6250	      const amountStr = (chargeCents / 100).toFixed(2);
6251	      const merchantRef = (invoice.checkoutVertical === "trades" ? "JOB-" : "RENT-") + invoice.id.slice(0, 8).toUpperCase();
6252	      const xId = crypto.randomBytes(16).toString("hex");
6253	      let sessionResult: any;
6254	      if (isWindcaveConfigured()) {
6255	        sessionResult = await createWindcaveSession(
6256	          xId, amountStr, merchantRef, party.email ?? "tenant@taptpay.co.nz", baseUrl, 0, 0,
6257	          { callbackBase: `${baseUrl}/api/checkout/callback?token=${token}`, notificationUrl: `${baseUrl}/api/windcave/${invoice.checkoutVertical === "trades" ? "trades" : "rent"}-notification` },
6258	        );
6259	      } else {
6260	        sessionResult = simulateRentSession(token, baseUrl);
6261	      }
6262	      if (!sessionResult.success) return res.status(502).json({ message: "Payment gateway error. Please try again." });
6263	      // Pin single-payment invoices to their one Windcave session so a stale or
6264	      // foreign session can't finalize them. Split invoices legitimately create
6265	      // one session per payer; pinning a single shared value would 403 every
6266	      // payer but the most recent, so we skip it and rely on per-session dedup
6267	      // (splitPaidSessions) instead.
6268	      if (sessionResult.sessionId && !isSplit) await updateCheckoutInvoice(invoice, { windcaveSessionId: sessionResult.sessionId });
6269	      // Duplicate X-ID — Windcave reports the session already completed; finalize now
6270	      // and bounce the payer back to the checkout page to see the result.
6271	      if (sessionResult.alreadyComplete) {
6272	        await finalizeCheckoutInvoice(invoice, !!sessionResult.approved, sessionResult.windcaveTransactionId, sessionResult.sessionId);
6273	        return res.json({ hppUrl: `${baseUrl}/r/${token}` });
6274	      }
6275	      if (!sessionResult.hppUrl) return res.status(502).json({ message: "Payment gateway error. Please try again." });
6276	      res.json({ hppUrl: sessionResult.hppUrl });
6277	    } catch (err) { console.error("[CHECKOUT_PAY]", err); res.status(500).json({ message: "Failed to initiate payment" }); }
6278	  });
6279	
6280	  // In-page (Hosted Fields) equivalent of /api/checkout/pay. Creates a Windcave
6281	  // session for the invoice and returns the AJAX submit URLs so the branded
6282	  // checkout page can take card / Apple Pay / Google Pay details in-page instead
6283	  // of redirecting the payer out to the external Windcave HPP. The URLs are
6284	  // cached server-side (never trusted from the client) and consumed at completion.
6285	  app.post("/api/checkout/:token/session", async (req, res) => {
